function PracticeMode({ initialSongId, onDone }) {
  const [selectedSong, setSelectedSong] = useState(() => {
    if (initialSongId) {
      const found = PRACTICE_SONGS.find(s => s.id === initialSongId);
      return found || PRACTICE_SONGS[0];
    }
    return PRACTICE_SONGS[0];
  });
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [countdown, setCountdown] = useState(null);
  const [streak, setStreak] = useState(() => {
    const sid = initialSongId || PRACTICE_SONGS[0].id;
    const p = loadProgress(sid);
    return p ? p.streak : 0;
  });
  const [totalCorrect, setTotalCorrect] = useState(() => {
    const sid = initialSongId || PRACTICE_SONGS[0].id;
    const p = loadProgress(sid);
    return p ? p.totalCorrect : 0;
  });
  const [feedback, setFeedback] = useState(null);
  const [beatPulse, setBeatPulse] = useState(false);
  const [audioReady, setAudioReady] = useState(true); // optimistic; flips to false when AudioContext can't reach 'running'

  const audioCtxRef = useRef(null);
  const timerRef = useRef(null);
  const countdownRef = useRef(null);
  const rAFRef = useRef(null);
  const lyricsContainerRef = useRef(null);
  const lineRefs = useRef([]);
  const playbackStartTimeRef = useRef(null);
  const cumulativeDurationsRef = useRef([]); // Cache of cumulative line durations
  const pausedElapsedRef = useRef(null); // Track elapsed time during pause (replaces window._pausedPlaybackElapsed)

  // If initialSongId changes (user picks a new song from SongLibrary), switch to it
  useEffect(() => {
    if (initialSongId) {
      const found = PRACTICE_SONGS.find(s => s.id === initialSongId);
      if (found) {
        setSelectedSong(found);
        resetSong();
      }
    }
  }, [initialSongId]);

  // Cleanup timers on unmount
  useEffect(() => {
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
      if (countdownRef.current) clearTimeout(countdownRef.current);
      if (rAFRef.current) cancelAnimationFrame(rAFRef.current);
      if (audioCtxRef.current) audioCtxRef.current.close();
    };
  }, []);

  // Persist practice progress to localStorage whenever it changes (issue #161).
  // Fires on mount too, but saves back the same values that were loaded — harmless.
  useEffect(() => {
    saveProgress(selectedSong.id, streak, totalCorrect);
  }, [streak, totalCorrect, selectedSong.id]);

  const resetSong = () => {
    setIsPlaying(false);
    setIsPaused(false);
    setCurrentIndex(0);
    setCountdown(null);
    setFeedback(null);
    playbackStartTimeRef.current = null;
    cumulativeDurationsRef.current = [];
    if (rAFRef.current) {
      cancelAnimationFrame(rAFRef.current);
      rAFRef.current = null;
    }
    if (timerRef.current) clearInterval(timerRef.current);
    if (countdownRef.current) clearTimeout(countdownRef.current);
  };

  const playNote = useCallback((freq) => {
    // AudioContext should be initialized by initAudioContext() before first playNote call
    if (!audioCtxRef.current) {
      // Fallback: create if somehow not initialized (shouldn't happen)
      audioCtxRef.current = new (window.AudioContext || window.webkitAudioContext)();
    }
    // Guard: never schedule audio into a suspended context (issue #155).
    // Notes scheduled into a suspended AudioContext produce no audio silently.
    // Skip gracefully — the practice timer keeps running, audio just won't play.
    // Log the cause (see issue #185) so it's clear this is a browser autoplay
    // limitation, not an app bug: a user gesture is required to start audio.
    if (audioCtxRef.current.state !== 'running') {
      console.warn(
        'Skipping chord playback: AudioContext state is ' + audioCtxRef.current.state +
        ' (expected "running"). Cause: browser autoplay policy requires a user gesture to ' +
        'start audio; tap "Enable Audio" or interact with the page. This is expected browser ' +
        'behavior — the practice timer continues, only the chord sound is skipped.'
      );
      setAudioReady(false);
      return;
    }
    const osc = audioCtxRef.current.createOscillator();
    const gain = audioCtxRef.current.createGain();
    osc.connect(gain);
    gain.connect(audioCtxRef.current.destination);
    osc.type = 'triangle';
    osc.frequency.value = freq;
    gain.gain.setValueAtTime(0.25, audioCtxRef.current.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, audioCtxRef.current.currentTime + 0.4);
    osc.start();
    osc.stop(audioCtxRef.current.currentTime + 0.4);
  }, []);

  const playChord = useCallback(async (chord) => {
    if (!chord) return;
    // Ensure AudioContext is initialized and resumed before playing
    await initAudioContext();
    const chordKey = Object.keys(CHORD_FREQ).find(k => k.toLowerCase() === chord.toLowerCase());
    const freqs = CHORD_FREQ[chordKey] || [440];
    freqs.forEach(freq => playNote(freq));
  }, [playNote]);

  // Auto-scroll the active line into view
  const scrollToLine = useCallback((idx) => {
    const el = lineRefs.current[idx];
    if (el) {
      el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  }, []);

  const cancelCountdown = () => {
    if (countdownRef.current) {
      clearTimeout(countdownRef.current);
      countdownRef.current = null;
    }
    if (rAFRef.current) {
      cancelAnimationFrame(rAFRef.current);
      rAFRef.current = null;
    }
    setCountdown(null);
  };

  // Initialize and resume AudioContext on user gesture.
  // Async because resume() returns a Promise; must be awaited in strict
  // autoplay-policy browsers (mobile Safari) where audio would otherwise fail
  // silently. On any failure (resume rejection OR context still suspended),
  // flip audioReady=false so the UI can surface a banner + Enable Audio button
  // tied to a fresh user gesture (issue #155).
  const initAudioContext = async () => {
    if (!audioCtxRef.current) {
      try {
        audioCtxRef.current = new (window.AudioContext || window.webkitAudioContext)();
      } catch (err) {
        console.warn(
          'Failed to create AudioContext: ' + (err && err.message ? err.message : err) + '. ' +
          'Cause: the Web Audio API may be unsupported or blocked in this browser. ' +
          'The practice timer will continue, but chord sounds are unavailable. This is ' +
          'an expected fallback in restricted environments, not an app bug (issue #207).'
        );
        setAudioReady(false);
        return;
      }
    }
    // Browsers start AudioContext in 'suspended' state - must resume on user gesture
    if (audioCtxRef.current.state === 'suspended') {
      try {
        await audioCtxRef.current.resume();
      } catch (err) {
        console.warn(
          'Failed to resume AudioContext: ' + (err && err.message ? err.message : err) + '. ' +
          'Cause: browser autoplay policy requires a user gesture (tap/click) to start audio; ' +
          'resume() is rejected outside a user gesture. This is an expected browser security ' +
          'limitation, not an app bug — engage with the page (tap "Enable Audio") to start audio (issue #206).'
        );
        setAudioReady(false);
        return;
      }
    }
    // Verify the context is actually running before declaring audio ready.
    // resume() can resolve without flipping state to 'running' on some browsers.
    if (audioCtxRef.current.state === 'running') {
      setAudioReady(true);
    } else {
      console.warn(
        'AudioContext state is ' + audioCtxRef.current.state + ' after resume() (expected "running"). ' +
        'Cause: browser autoplay policy requires a user gesture to start audio, and some browsers ' +
        'resolve resume() without flipping state to "running". This is an expected browser security ' +
        'limitation, not an app bug — the user must interact with the page (tap "Enable Audio") to ' +
        'start audio.'
      );
      setAudioReady(false);
    }
  };

  const startAutoplay = async () => {
    // Initialize audio context on user gesture (required by browsers)
    // Awaiting ensures the context is fully resumed before playback starts;
    // the countdown gives ample time for resume() to complete.
    await initAudioContext();

    // Use rAF with performance.now() for precise, drift-free countdown timing
    const startTime = performance.now();
    const COUNTDOWN_DURATION = 2400; // 3 counts * 800ms each
    const GO_DURATION = 600;

    const countdownFrame = () => {
      const elapsed = performance.now() - startTime;

      if (elapsed < COUNTDOWN_DURATION) {
        // Calculate which count to display based on elapsed time
        const countIndex = Math.floor(elapsed / 800); // 0=3, 1=2, 2=1
        const countValue = 3 - countIndex;
        setCountdown(countValue);
        rAFRef.current = requestAnimationFrame(countdownFrame);
      } else if (elapsed < COUNTDOWN_DURATION + GO_DURATION) {
        // Show "Go!"
        setCountdown('Go!');
        rAFRef.current = requestAnimationFrame(countdownFrame);
      } else {
        // Start playback
        setCountdown(null);
        beginPlayback();
      }
    };

    rAFRef.current = requestAnimationFrame(countdownFrame);
  };

  // Pre-calculate cumulative durations for all lines (for rAF timing)
    const calculateCumulativeDurations = useCallback(() => {
      const durations = [];
      let cumulative = 0;
      // Inline duration calculation to avoid dependency on unstable lineDuration function
      const barDur = (60 / selectedSong.bpm) * 4000;
      for (const line of selectedSong.lyrics) {
        const lineDur = barDur * ((line.beats || 4) / 4);
        cumulative += lineDur;
        durations.push(cumulative);
      }
      return durations;
    }, [selectedSong]);

    // rAF-based playback loop - self-correcting timing
    const playbackLoop = useCallback(() => {
      if (!playbackStartTimeRef.current || isPaused) return;

      const elapsed = Date.now() - playbackStartTimeRef.current;
      const cumulative = cumulativeDurationsRef.current;

      // Find which line we should be on based on elapsed time
      let targetIndex = 0;
      for (let i = 0; i < cumulative.length; i++) {
        if (elapsed >= cumulative[i]) {
          targetIndex = i + 1;
        } else {
          break;
        }
      }

      // If we've reached the end
      if (targetIndex >= selectedSong.lyrics.length) {
        if (rAFRef.current) {
          cancelAnimationFrame(rAFRef.current);
          rAFRef.current = null;
        }
        playbackStartTimeRef.current = null;
        setIsPlaying(false);
        setIsPaused(false);
        setFeedback({ type: 'complete', message: '🎵 Song complete! Great practice!' });
        if (onDone) onDone();
        return;
      }

      // If we've advanced to a new line
      if (targetIndex !== currentIndex) {
        setCurrentIndex(targetIndex);
        setBeatPulse(true);
        setTimeout(() => setBeatPulse(false), 150);
        setFeedback(null);
        scrollToLine(targetIndex);

        // Play chord on beat
        const chord = selectedSong.lyrics[targetIndex].chord;
        if (chord) {
          playChord(chord);
        }
      }

      // Continue the loop
      rAFRef.current = requestAnimationFrame(playbackLoop);
    }, [currentIndex, isPaused, selectedSong, onDone, scrollToLine, playChord]);

    const beginPlayback = () => {
      setIsPlaying(true);
      setIsPaused(false);
      setCurrentIndex(0);
      playbackStartTimeRef.current = Date.now();
      cumulativeDurationsRef.current = calculateCumulativeDurations();

      // Pulse animation on the beat
      setBeatPulse(true);
      setTimeout(() => setBeatPulse(false), 150);

      // Play first chord immediately
      if (selectedSong.lyrics[0].chord) {
        playChord(selectedSong.lyrics[0].chord);
      }

      // Start rAF loop
      rAFRef.current = requestAnimationFrame(playbackLoop);
    };

    const pauseAutoplay = () => {
      if (rAFRef.current) {
        cancelAnimationFrame(rAFRef.current);
        rAFRef.current = null;
      }
      // Adjust start time so elapsed time is preserved on resume
      if (playbackStartTimeRef.current) {
        const elapsed = Date.now() - playbackStartTimeRef.current;
        // We'll subtract this elapsed from the new start time on resume
        playbackStartTimeRef.current = null;
        // Store elapsed in a ref (replaces window._pausedPlaybackElapsed)
        pausedElapsedRef.current = elapsed;
      }
      setIsPaused(true);
    };

    const resumeAutoplay = () => {
      if (!isPaused) return;

      setIsPaused(false);
      // Start from where we left off, accounting for elapsed time
      const elapsedWhilePaused = pausedElapsedRef.current || 0;
      pausedElapsedRef.current = null;
      playbackStartTimeRef.current = Date.now() - elapsedWhilePaused;
      cumulativeDurationsRef.current = calculateCumulativeDurations();

      // Pulse animation on resume
      setBeatPulse(true);
      setTimeout(() => setBeatPulse(false), 150);

      // Resume rAF loop
      rAFRef.current = requestAnimationFrame(playbackLoop);
    };

  const stopAutoplay = () => {
    if (timerRef.current) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
    setIsPlaying(false);
  };

  const markCorrect = () => {
    setFeedback({ type: 'correct', message: '✓ Nice!' });
    setStreak(s => s + 1);
    setTotalCorrect(t => t + 1);
    if (selectedSong.lyrics[currentIndex].chord) {
      playChord(selectedSong.lyrics[currentIndex].chord);
    }
  };

  const markIncorrect = () => {
    setFeedback({ type: 'incorrect', message: '✗ Keep trying!' });
    setStreak(s => Math.max(0, s - 1));
  };

  const resetProgress = () => {
    let storageReset = true;
    if (typeof localStorage !== 'undefined') {
      try {
        localStorage.removeItem(`practice-progress-${selectedSong.id}`);
      } catch (e) {
        // localStorage not available, disabled, or threw (e.g. private
        // browsing, security exception). Don't silently swallow — surface it
        // so the user knows their persisted streak may re-appear on reload.
        // See issue #171: previous empty catch(e){} hid this from users.
        console.warn(`Failed to clear practice progress for "${selectedSong.id}" from localStorage:`, e?.message || e);
        storageReset = false;
      }
    }
    // Always reset the in-memory session counters so the current view behaves
    // correctly during this session.
    setStreak(0);
    setTotalCorrect(0);
    setFeedback(
      storageReset
        ? { type: 'info', message: '🔄 Progress reset for this song' }
        : {
            type: 'incorrect',
            message: '⚠️ Reset this session, but could not clear saved progress (storage unavailable). It may return on reload.',
          }
    );
  };

  const goToLine = (idx, playChordOnNavigate = false) => {
    if (idx >= 0 && idx < selectedSong.lyrics.length) {
      if (timerRef.current) {
        clearTimeout(timerRef.current);
        timerRef.current = null;
      }
      setIsPlaying(false);
      setCurrentIndex(idx);
      setFeedback(null);
      scrollToLine(idx);
      // Play chord for the new line if requested (for consistent UX with autoplay)
      if (playChordOnNavigate) {
        const chord = selectedSong.lyrics[idx].chord;
        if (chord) {
          playChord(chord);
        }
      }
    }
  };

  const nextLine = () => {
    if (currentIndex < selectedSong.lyrics.length - 1) {
      goToLine(currentIndex + 1, true);
    }
  };

  const prevLine = () => {
    if (currentIndex > 0) {
      goToLine(currentIndex - 1, true);
    }
  };

  const current = selectedSong?.lyrics ? selectedSong.lyrics[currentIndex] : null;

  if (!selectedSong) {
    return (
      <div className="section" style={{ textAlign: 'center', padding: '2rem' }}>
        <p>Song not found. Please select a song from the dropdown.</p>
      </div>
    );
  }

  if (!current) {
    return (
      <div className="section" style={{ textAlign: 'center', padding: '2rem' }}>
        <p>Lyrics not found for the selected song.</p>
      </div>
    );
  }

  return (
    <div className="section">
      <h2 className="section-title">Practice Mode</h2>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
        <div style={{ display: 'flex', gap: '0.5rem', alignItems: 'center' }}>
          <select
            value={selectedSong?.id || ''}
            onChange={e => {
              const song = PRACTICE_SONGS.find(s => s.id === Number(e.target.value));
              setSelectedSong(song);
              resetSong();
              // Load saved progress for the new song (issue #161)
              const p = loadProgress(song.id);
              setStreak(p ? p.streak : 0);
              setTotalCorrect(p ? p.totalCorrect : 0);
            }}
            disabled={isPlaying}
            className="song-selector"
            style={{ padding: '0.5rem', borderRadius: 8, border: 'none', background: 'var(--bg-tertiary)', color: 'var(--text-primary)', fontSize: '0.9rem' }}
          >
            {PRACTICE_SONGS.map(s => <option key={s.id} value={s.id}>{s.title}</option>)}
          </select>
          <span style={{ color: 'var(--text-secondary)', fontSize: '0.85rem' }}>
            {selectedSong.bpm} BPM • {selectedSong.artist}
          </span>
        </div>
        <div>
          {!isPlaying && countdown === null && (
            <button className="control-btn" onClick={startAutoplay} style={{ background: 'var(--accent-primary)', color: 'white', fontSize: '1rem', padding: '0.6rem 1.5rem' }}>
              ▶ Start
            </button>
          )}
          {isPlaying && !isPaused && (
            <>
              <button className="control-btn" onClick={pauseAutoplay} style={{ background: 'var(--warning)', color: 'white', marginRight: '0.5rem' }}>
                ⏸ Pause
              </button>
              <button className="control-btn" onClick={stopAutoplay} style={{ background: 'var(--danger)', color: 'white' }}>
                ⏹ Stop
              </button>
            </>
          )}
          {isPlaying && isPaused && (
            <>
              <button className="control-btn" onClick={resumeAutoplay} style={{ background: 'var(--success)', color: 'white', marginRight: '0.5rem' }}>
                ▶ Resume
              </button>
              <button className="control-btn" onClick={stopAutoplay} style={{ background: 'var(--danger)', color: 'white' }}>
                ⏹ Stop
              </button>
            </>
          )}
        </div>
      </div>

      {/* Audio unavailable banner (issue #155): surfaces a visible warning and
          an Enable Audio button tied to a fresh user gesture when AudioContext
          could not reach 'running' (mobile Safari strict autoplay policy). */}
      {!audioReady && (
        <div
          role="alert"
          aria-live="assertive"
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            gap: '1rem',
            padding: '0.75rem 1rem',
            marginBottom: '1rem',
            background: 'rgba(239, 68, 68, 0.12)',
            border: '1px solid rgba(239, 68, 68, 0.45)',
            borderRadius: '8px',
            color: 'var(--text-primary)',
            fontSize: '0.9rem',
          }}
        >
          <span>⚠ Audio unavailable — practice timer will continue but chords will be silent until audio is enabled.</span>
          <button
            type="button"
            className="control-btn"
            onClick={initAudioContext}
            aria-label="Enable Audio"
            style={{
              background: 'var(--accent-primary)',
              color: 'white',
              fontSize: '0.9rem',
              padding: '0.5rem 1rem',
              flexShrink: 0,
            }}
          >
            🔊 Enable Audio
          </button>
        </div>
      )}

      {/* Countdown overlay */}
      {countdown !== null && (
        <div style={{
          position: 'relative', height: '300px', display: 'flex',
          alignItems: 'center', justifyContent: 'center',
          background: 'var(--bg-tertiary)', borderRadius: 'var(--border-radius)',
          marginBottom: '1rem'
        }}>
          <span style={{ 
            fontSize: countdown === 'Go!' ? '4rem' : '6rem', 
            fontWeight: 'bold',
            color: countdown === 'Go!' ? 'var(--success)' : 'var(--accent-primary)',
            animation: 'countdownPop 0.6s ease-out'
          }}>
            {countdown}
          </span>
          <button 
            onClick={cancelCountdown}
            className="control-btn" 
            style={{ 
              position: 'absolute', 
              bottom: '20px', 
              background: 'var(--bg-secondary)', 
              color: 'var(--text-primary)',
              fontSize: '1rem',
              padding: '0.4rem 1rem'
            }}
          >
            Cancel
          </button>
        </div>
      )}

      {/* Main practice display — karaoke style */}
      {countdown === null && (
        <div 
          style={{
            background: 'var(--bg-tertiary)',
            borderRadius: 'var(--border-radius)',
            padding: '1rem 1.25rem',
            position: 'relative',
            overflow: 'hidden',
            marginBottom: '1rem'
          }}
        >
          {/* Current chord display — big and prominent */}
          {current.chord && (
            <div style={{
              textAlign: 'center',
              marginBottom: '0.5rem',
              padding: '0.5rem',
            }}>
              <span style={{
                fontSize: '2.2rem',
                fontWeight: 'bold',
                color: 'var(--accent-primary)',
                display: 'inline-block',
                padding: '0.3rem 1.2rem',
                borderRadius: '12px',
                background: beatPulse ? 'rgba(102, 126, 234, 0.2)' : 'transparent',
                transform: beatPulse ? 'scale(1.15)' : 'scale(1)',
                transition: 'transform 0.1s ease-out, background 0.1s ease-out',
                textShadow: beatPulse ? '0 0 20px rgba(102, 126, 234, 0.6)' : 'none',
              }}>
                {current.chord}
              </span>
            </div>
          )}

          {/* Lyrics lines — with inline indicator on active line */}
          <div 
            ref={lyricsContainerRef}
            style={{ 
              maxHeight: '420px', 
              overflowY: 'auto',
              scrollBehavior: 'smooth',
              padding: '0.5rem 1rem',
            }}
          >
            {selectedSong.lyrics.map((line, idx) => {
              const isCurrent = idx === currentIndex;
              const isPast = idx < currentIndex;
              const isUpcoming = idx > currentIndex;

              return (
                <div
                  key={idx}
                  ref={el => lineRefs.current[idx] = el}
                  role="button"
                  tabIndex={isPlaying ? -1 : 0}
                  aria-label={`Line ${idx + 1}${line.chord ? `, chord: ${line.chord}` : ''}`}
                  aria-current={isCurrent ? 'step' : undefined}
                  onClick={() => !isPlaying && goToLine(idx, true)}
                  onKeyDown={e => {
                    if (!isPlaying && (e.key === 'Enter' || e.key === ' ')) {
                      e.preventDefault();
                      goToLine(idx, true);
                    }
                  }}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '0.5rem',
                    padding: '0.5rem 0.75rem',
                    margin: '0.15rem 0',
                    borderRadius: '8px',
                    cursor: isPlaying ? 'default' : 'pointer',
                    background: isCurrent 
                      ? (beatPulse ? 'rgba(102, 126, 234, 0.15)' : 'rgba(255, 255, 255, 0.06)')
                      : 'transparent',
                    transition: 'all 0.2s ease',
                    borderLeft: isCurrent ? '3px solid var(--accent-primary)' : '3px solid transparent',
                    opacity: isPast ? 0.4 : isUpcoming ? 0.55 : 1,
                  }}
                >
                  {/* Indicator dot — moves with the line */}
                  <span style={{
                    display: 'inline-flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    width: '1.2rem',
                    height: '1.2rem',
                    flexShrink: 0,
                  }}>
                    <span style={{
                      display: 'inline-block',
                      width: isCurrent ? '10px' : '6px',
                      height: isCurrent ? '10px' : '6px',
                      borderRadius: '50%',
                      background: isCurrent ? 'var(--accent-primary)' : 'transparent',
                      boxShadow: isCurrent ? '0 0 10px rgba(102, 126, 234, 0.7)' : 'none',
                      animation: isPlaying && isCurrent ? 'bounce 0.5s infinite alternate' : 'none',
                      transition: 'all 0.2s ease',
                    }} />
                  </span>
                  {/* Lyric content */}
                  <div style={{ display: 'flex', flexDirection: 'column' }}>
                    {line.chord && (
                      <span style={{
                        fontSize: '0.7rem',
                        fontWeight: '600',
                        color: isCurrent ? 'var(--accent-primary)' : 'var(--text-secondary)',
                        opacity: isCurrent ? 1 : 0.6,
                      }}>
                        {line.chord}
                      </span>
                    )}
                    <span style={{
                      fontSize: isCurrent ? '1.3rem' : '1rem',
                      fontWeight: isCurrent ? '600' : '400',
                      color: isCurrent ? 'var(--text-primary)' : 'var(--text-secondary)',
                      lineHeight: '1.4',
                    }}>
                      {line.text}
                    </span>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Feedback display */}
      {feedback && (
        <div style={{
          textAlign: 'center',
          padding: '0.75rem',
          borderRadius: '8px',
          background: feedback.type === 'correct' ? 'rgba(0, 255, 136, 0.1)' 
                     : feedback.type === 'incorrect' ? 'rgba(255, 77, 77, 0.1)' 
                     : feedback.type === 'complete' ? 'rgba(102, 126, 234, 0.15)'
                     : 'var(--bg-tertiary)',
          marginBottom: '0.75rem',
          animation: 'fadeInUp 0.3s ease-out',
        }}>
          <span style={{ 
            fontSize: '1.2rem',
            color: feedback.type === 'correct' ? 'var(--success)'
                 : feedback.type === 'incorrect' ? 'var(--danger)'
                 : feedback.type === 'complete' ? 'var(--accent-primary)'
                 : 'var(--text-primary)',
          }}>
            {feedback.message}
          </span>
        </div>
      )}

      {/* Status bar */}
      <div style={{
        display: 'flex',
        justifyContent: 'space-around',
        alignItems: 'center',
        padding: '0.75rem',
        background: 'var(--bg-tertiary)',
        borderRadius: 'var(--border-radius)',
        marginBottom: '0.75rem',
      }}>
        <span>🔥 {streak}</span>
        <span>{currentIndex + 1} / {selectedSong.lyrics.length}</span>
        <span>✓ {totalCorrect}</span>
        <button
          onClick={resetProgress}
          aria-label="Reset practice progress for this song"
          title="Reset progress"
          style={{
            background: 'none',
            border: 'none',
            color: 'var(--text-secondary)',
            fontSize: '0.75rem',
            cursor: 'pointer',
            textDecoration: 'underline',
            padding: '0.25rem 0.5rem',
            opacity: 0.6,
          }}
          onMouseEnter={(e) => e.target.style.opacity = '1'}
          onMouseLeave={(e) => e.target.style.opacity = '0.6'}
        >
          Reset
        </button>
      </div>

      {/* Action buttons */}
      <div style={{ display: 'flex', gap: '0.75rem', justifyContent: 'center', flexWrap: 'wrap' }}>
        <button className="control-btn" onClick={prevLine} aria-label="Previous line" disabled={currentIndex === 0}>
          ← Prev
        </button>
        <button 
          className="control-btn" 
          onClick={markCorrect}
          aria-label="Mark as correct"
          style={{ background: 'var(--success)', color: 'white' }}
        >
          ✓ Got it!
        </button>
        <button 
          className="control-btn" 
          onClick={markIncorrect}
          aria-label="Mark as missed"
          style={{ background: 'var(--danger)', color: 'white' }}
        >
          ✗ Missed
        </button>
        <button 
          className="control-btn" 
          onClick={() => current.chord && playChord(current.chord)}
          aria-label="Play chord sound"
          style={{ background: 'var(--accent-secondary)' }}
        >
          🔊 Play
        </button>
        <button className="control-btn" onClick={nextLine} aria-label="Next line" disabled={currentIndex === selectedSong.lyrics.length - 1}>
          Next →
        </button>
      </div>
    </div>
  );
}

export default PracticeMode;
export { PRACTICE_SONGS };
